import { inject, onBeforeUnmount, onMounted, provide, ref, useId, type InjectionKey } from "vue";
import { useFloatingLayer, useReducedMotion } from "../../../lib/composables";
import { useMotionState } from "../../state";
export type MenuPoint = { x: number; y: number };
export type MenuInput = "pointer" | "keyboard" | "touch";
export function provideMenu(props: { open?: boolean; defaultOpen?: boolean }, emit: (...args: any[]) => void) {
  const open = useMotionState(props, emit, "open", props.defaultOpen ?? false);
  const point = ref<MenuPoint>({ x: 0, y: 0 }), modality = ref<MenuInput>("pointer");
  const invocation = ref(0), activeId = ref<string | null>(null);
  const trigger = ref<HTMLElement | null>(null), contentRef = ref<HTMLElement | null>(null);
  const id = useId(), reduce = useReducedMotion();
  const layer = useFloatingLayer(open, contentRef);
  function setOpen(value: boolean) { open.value = value; if (!value) activeId.value = null; }
  const close = () => { setOpen(false); trigger.value?.focus(); };
  const state = { open, point, modality, invocation, activeId, trigger, contentRef, id, reduce, layer, setOpen, close,
    openAt(position: MenuPoint, input: MenuInput) { point.value = position; modality.value = input; ++invocation.value; activeId.value = null; setOpen(true); },
  };
  provide(menuKey, state);
  const escape = (event: KeyboardEvent) => { if (layer.claimEscape(event)) close(); };
  const dismiss = (event: PointerEvent) => {
    if (open.value && !layer.containsHigher(event.target) && !contentRef.value?.contains(event.target as Node)) setOpen(false);
  };
  const windowChanged = () => { if (open.value) setOpen(false); };
  const bindings = () => [
    [document, "keydown", escape], [window, "pointerdown", dismiss],
    [window, "resize", windowChanged], [window, "scroll", windowChanged],
  ] as const;
  onMounted(() => { for (const [node, type, listener] of bindings()) node.addEventListener(type, listener as EventListener); });
  onBeforeUnmount(() => { for (const [node, type, listener] of bindings()) node.removeEventListener(type, listener as EventListener); });
  return state;
}
export type MenuState = ReturnType<typeof provideMenu>;
const menuKey: InjectionKey<MenuState> = Symbol("orvui-menu");
export function useMenu() {
  const state = inject(menuKey);
  if (!state) throw new Error("A context menu part requires ContextMenu");
  return state;
}

import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from "vue";
import type { MenuState } from "./menu-state";
const bound = (value: number, maximum: number, minimum = 0) => Math.max(minimum, Math.min(value, maximum));
export function useMenuSurface(ctx: MenuState) {
  const mounted = ref(false), morphReady = ref(false);
  const position = ref({ x: 0, y: 0 });
  const geometry = ref({ x: 0, y: 0, width: 0, height: 0 });
  const collapsed = computed(() => {
    const { x, y, width, height } = geometry.value;
    const edges = [bound(y - 8, height), bound(width - x - 8, width), bound(height - y - 8, height), bound(x - 8, width)];
    return `inset(${edges.map(edge => `${edge}px`).join(" ")} round 10px)`;
  });
  const visualOpen = computed(() => ctx.open.value && morphReady.value);
  const frames = new Set<number>();
  let version = 0, prefix = "";
  let prefixExpiry: ReturnType<typeof setTimeout> | undefined;
  function cancelFrames() { frames.forEach(cancelAnimationFrame); frames.clear(); }
  function frame(fn: () => void, token: number) {
    const id = requestAnimationFrame(() => { frames.delete(id); if (mounted.value && ctx.open.value && token === version) fn(); });
    frames.add(id);
  }
  function items() { return Array.from(ctx.contentRef.value?.querySelectorAll<HTMLElement>('[data-context-menu-item="true"]:not([data-disabled="true"])') ?? []); }
  async function prepare() {
    const token = ++version;
    cancelFrames(); morphReady.value = false;
    if (!mounted.value || !ctx.open.value) return;
    await nextTick();
    if (!mounted.value || !ctx.open.value || token !== version) return;
    const element = ctx.contentRef.value;
    if (!element) return;
    const { width, height } = element.getBoundingClientRect();
    const { x, y } = ctx.point.value;
    const left = bound(x, Math.max(8, innerWidth - width - 8), 8);
    const top = bound(y, Math.max(8, innerHeight - height - 8), 8);
    position.value = { x: left, y: top };
    geometry.value = { width, height, x: bound(x - left, Math.max(12, width - 12), 12), y: bound(y - top, Math.max(12, height - 12), 12) };
    element.dataset.invocation = String(ctx.invocation.value);
    if (ctx.reduce.value || ctx.modality.value === "keyboard") morphReady.value = true;
    else frame(() => frame(() => { morphReady.value = true; }, token), token);
    frame(() => items()[0]?.focus({ preventScroll: true }), token);
  }
  function key(event: KeyboardEvent) {
    if (event.defaultPrevented) return;
    if (event.key === "Escape") { if (ctx.layer.claimEscape(event)) ctx.close(); return; }
    if (event.key === "Tab") { ctx.setOpen(false); return; }
    const choices = items();
    const commands = ["ArrowDown", "ArrowUp", "Home", "End"];
    if (commands.includes(event.key)) {
      event.preventDefault();
      const index = choices.indexOf(document.activeElement as HTMLElement);
      const next = event.key === "Home" ? 0 : event.key === "End" ? choices.length - 1
        : index < 0 ? 0 : (index + (event.key === "ArrowDown" ? 1 : -1) + choices.length) % choices.length;
      choices[next]?.focus(); return;
    }
    if (event.key.length !== 1 || event.ctrlKey || event.metaKey || event.altKey) return;
    prefix += event.key.toLocaleLowerCase();
    clearTimeout(prefixExpiry);
    prefixExpiry = setTimeout(() => { prefix = ""; }, 500);
    choices.find(choice => (choice.dataset.label ?? choice.textContent ?? "").trim().toLocaleLowerCase().startsWith(prefix))?.focus();
  }
  watch(() => [ctx.open.value, ctx.invocation.value, ctx.point.value], prepare, { flush: "post" });
  onMounted(() => { mounted.value = true; void prepare(); });
  onBeforeUnmount(() => { mounted.value = false; ++version; cancelFrames(); clearTimeout(prefixExpiry); });
  return { mounted, morphReady, position, collapsed, visualOpen, key };
}

import { onBeforeUnmount } from "vue";
import type { MenuPoint, MenuState } from "./menu-state";
export function useMenuGesture(ctx: MenuState, disabled: () => boolean | undefined) {
  let pending: ReturnType<typeof setTimeout> | undefined;
  let origin: MenuPoint | undefined;
  let restore: (() => void) | undefined;
  const cancel = () => { clearTimeout(pending); pending = undefined; origin = undefined; };
  const end = () => { cancel(); restore?.(); restore = undefined; };
  onBeforeUnmount(end);
  function pointerdown(event: PointerEvent) {
    if (event.defaultPrevented || disabled() || !["touch", "pen"].includes(event.pointerType)) return;
    end();
    const surface = event.currentTarget as HTMLElement;
    const selection = [surface.style.userSelect, surface.style.webkitUserSelect];
    surface.style.userSelect = surface.style.webkitUserSelect = "none";
    restore = () => { [surface.style.userSelect, surface.style.webkitUserSelect] = selection; };
    const point = origin = { x: event.clientX, y: event.clientY };
    pending = setTimeout(() => { pending = undefined; origin = undefined; ctx.openAt(point, "touch"); }, 520);
  }
  return {
    onPointerdown: pointerdown,
    onPointermove(event: PointerEvent) { if (origin && Math.hypot(event.clientX - origin.x, event.clientY - origin.y) > 10) cancel(); },
    onPointerup: end, onPointercancel: end,
    onContextmenu(event: MouseEvent) {
      if (event.defaultPrevented || disabled()) return;
      event.preventDefault(); end(); ctx.openAt({ x: event.clientX, y: event.clientY }, "pointer");
    },
    onKeydown(event: KeyboardEvent) {
      if (event.defaultPrevented || disabled() || !(event.key === "ContextMenu" || event.shiftKey && event.key === "F10")) return;
      event.preventDefault();
      const rect = (event.currentTarget as HTMLElement).getBoundingClientRect();
      ctx.openAt({ x: rect.left + Math.min(24, rect.width / 2), y: rect.top + rect.height / 2 }, "keyboard");
    },
  };
}

import { computed, ref, type Ref, type WritableComputedRef } from "vue";

/** A value may move between parent control and local ownership during its life. */
export function useMotionState<T>(
  props: Record<string, any>,
  emit: (...args: any[]) => void,
  key: string,
  fallback: T,
): WritableComputedRef<T> {
  const memory = ref(fallback) as Ref<T>;
  return computed({
    get(): T {
      const supplied = props[key];
      return supplied === undefined ? memory.value : supplied;
    },
    set(requested: T) {
      memory.value = requested;
      emit(`update:${key}`, requested);
      if (key === "modelValue") emit("change", requested);
    },
  });
}

/** Rove focus within the event surface, using its own document. */
export function focusList(event: KeyboardEvent, selector = "button:not(:disabled)") {
  const direction = new Map<string, number>([
    ["ArrowDown", 1], ["ArrowRight", 1], ["ArrowUp", -1], ["ArrowLeft", -1],
  ]).get(event.key);
  if (direction === undefined && event.key !== "Home" && event.key !== "End") return;
  const surface = event.currentTarget as HTMLElement | null;
  if (!surface) return;
  const candidates = [...surface.querySelectorAll<HTMLElement>(selector)];
  if (!candidates.length) return;
  const current = candidates.indexOf(surface.ownerDocument.activeElement as HTMLElement);
  const index = event.key === "Home" ? 0
    : event.key === "End" ? candidates.length - 1
    : current === -1 ? (direction === -1 ? candidates.length - 1 : 0)
    : (current + direction! + candidates.length) % candidates.length;
  event.preventDefault();
  candidates[index]?.focus();
}

@import "tailwindcss";
@import "./tokens.css";
@source "./**/*.{vue,ts}";
@source not "./**/tests/**";
@custom-variant dark (&:where(.dark, .dark *));

:root { --announcement-h: 2.5rem; }

@theme {
  --background-image-brand-bg: var(--gradient-bg);
  --background-image-brand-accent: var(--gradient-accent);
  --animate-marquee: marquee 30s linear infinite;
  --animate-marquee-vertical: marquee-vertical 30s linear infinite;
  --animate-rainbow-border: rainbow-border 3s linear infinite;
  --animate-shimmer: shimmer 2.5s linear infinite;
  --animate-action-send: action-send 520ms var(--ease-out) both;
  --animate-action-copy: action-copy 520ms var(--ease-out) both;
  --animate-action-download: action-download 540ms var(--ease-out) both;
  --animate-action-archive: action-archive 520ms var(--ease-out) both;
  --animate-action-bell: action-bell 680ms var(--ease-out) both;
  --animate-action-settings: action-settings 720ms var(--ease-out) both;
}

/* Named motion tracks are part of the public styling contract. */
@keyframes marquee { to { transform: translateX(calc(-100% - var(--gap, 1rem))); } }
@keyframes marquee-vertical { to { transform: translateY(calc(-100% - var(--gap, 1rem))); } }
@keyframes rainbow-border {
  from { background-position: 0% 50%; }
  to { background-position: 100% 50%; }
}
@keyframes shimmer {
  from { background-position: 200% 0; }
  to { background-position: -200% 0; }
}
@keyframes action-send {
  0%, 100% { transform: translate(0, 0); }
  45% { transform: translate(2px, -2px); }
}
@keyframes action-copy {
  0%, 100% { transform: translate(0, 0); }
  40% { transform: translate(1.5px, -1.5px); }
  70% { transform: translate(-1px, 1px); }
}
@keyframes action-download {
  0%, 100% { transform: translateY(0); }
  42% { transform: translateY(2.5px); }
}
@keyframes action-archive {
  0%, 100% { transform: scale(1); }
  45% { transform: scale(0.9); }
}
@keyframes action-bell {
  0%, 100% { transform: rotate(0deg); }
  18% { transform: rotate(14deg); }
  36% { transform: rotate(-12deg); }
  54% { transform: rotate(8deg); }
  72% { transform: rotate(-5deg); }
}
@keyframes action-settings {
  from { transform: rotate(0deg); }
  to { transform: rotate(90deg); }
}

@layer base {
  html, body { overflow-x: clip; }
  html { color-scheme: light dark; }
  body {
    font-family: var(--font-sans);
    color: var(--foreground);
    background: var(--background);
    text-rendering: optimizeLegibility;
    -webkit-font-smoothing: antialiased;
  }
  a, button:not(:disabled), [role="button"]:not(:disabled) { cursor: pointer; }
  ::selection {
    color: var(--foreground);
    background: color-mix(in oklch, var(--accent) 30%, transparent);
  }
  .shiki, .shiki span { color: var(--shiki-light); }
  .dark .shiki, .dark .shiki span { color: var(--shiki-dark); }
}

@layer utilities {
  .text-balance { text-wrap: balance; }
  .text-pretty { text-wrap: pretty; }
  .scrollbar-hide { scrollbar-width: none; }
  .scrollbar-hide::-webkit-scrollbar { display: none; }
  .mask-b-fade { mask-image: linear-gradient(to bottom, black 60%, transparent); }
  .mask-radial-fade { mask-image: radial-gradient(ellipse at center, black 40%, transparent 75%); }
  .grid-noise {
    background-size: 32px 32px;
    background-image: linear-gradient(to right, color-mix(in oklch, var(--foreground) 6%, transparent) 1px, transparent 1px), linear-gradient(to bottom, color-mix(in oklch, var(--foreground) 6%, transparent) 1px, transparent 1px);
  }
  .glass {
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
    backdrop-filter: blur(20px) saturate(160%);
    box-shadow: inset 0 1px 0 0 rgb(255 255 255 / 0.06), 0 24px 60px -24px rgb(0 0 0 / 0.45);
  }
  .glass-strong { background: var(--glass-strong-bg); backdrop-filter: blur(16px); }
  .glass-thin { background: var(--glass-thin-bg); backdrop-filter: blur(12px); border: 1px solid var(--glass-border); }
  .press { transition: transform 120ms var(--ease-out); }
  .press:active { transform: scale(0.97); }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

